from pathlib import Path
import json
P=Path(__file__).resolve().parent
p=P/'review-notes.json';data=json.loads(p.read_text('utf-8'));data['records']=data['records'][:9]
rows=[
('A10','First hurt pose, short interpolation, hitbox/body separation, root-node position and combo reach, nine reaction categories, proportion/weapon differences, asymmetry and brief distortion are retained.','Root markers and isolated torso orientation are actually visible in current encoded samples. First-pose interpolation versus hit-stop could be tied to one timeline.','P2','01:28–02:20','Clarify the order of connection into the hurt pose and the pose hold. Do not imply that instant snapping and short interpolation are the same operation.'),
('A11','2D versus 3D interpolation, identical eight-frame total with changed internal timing, reading anticipation, uppercut key poses, different return path, and contextual speed are retained.','Kula footage is verified KOF XIII sprite footage; the suspected pixel-art/3D mismatch is dismissed. Eight-frame A/B and return trajectory guides are visible.','P2','00:02–01:05','Explain the comparison goal over the initial normal-speed passes rather than waiting until the long opening demonstration has finished.'),
('A12','Small-screen expression, image retouch before model changes, jaw structure, eye whites and teeth, genre-specific expression, robot faces and constrained identity are retained.','Actual human-face closeups and small-versus-large comparison are visible. Animal Crossing eye-white observation is supported by the image; no factual error found there.','P2','02:26–03:20','Show the actual original face → retouch target → changed model as one linked comparison. The sampled game appearance menu is related but does not by itself demonstrate that workflow.'),
('A13','Rotation versus mirroring, sprite and 3D differences, hand/prop swapping, asymmetric-character exceptions, gameplay camera readability, and symmetric letter shapes are retained.','Targeted follow-up found the hand/prop A/B at02:32–02:44; it is NOT missing. The initial walking frame was before that demonstration.','P2','02:32–02:44','Enlarge the hands and handle and label anatomical left/right. The current small handle and full-body framing make the swap hard to read on mobile.'),
('A14','Cancel-to-next-action blending, different incoming poses for one walk, weight and duration, long-transition costs, directional blending, body layers/terrain and expression/engineering balance are retained.','Directional defense and slope adjustment are visible. The promised two-track timeline is absent in all six targeted frames of its narrated explanation.','P1','02:47–03:04','Show attack and walk clip tracks, their overlap, playhead and independent weight in the same frame. Current output instead shows gameplay or a paired walk with a weight chip, leaving the narrated two lines impossible to locate.'),
('A15','Diagonal grip versus perpendicular grip, finger complexity, fixed/swapped hand poses, hardware comparison conditions, cost allocation and crowd scaling are retained.','Grip closeups, swapped/continuous finger comparison and near/far framing are present. Grip-direction difference is visually small and lacks axis guides.','P2','01:11–01:23;03:31–03:54','Add handle/finger direction guides to the existing closeup. Replace the extended20/80 arithmetic and its follow-up caveats with visible crowd scaling and one cost condition.'),
('A16','Expanded hit regions, common combat plane, visual/path mismatch, active timing and hit-stop pose, animator/planner collaboration are retained.','Actual narrow/wide region, side/top view, and active-window comparisons are present. Terms are introduced before use.','P2','02:25–02:40','Keep the side/top comparison during the displaced-hitbox explanation. The sampled monster closeup does not reveal the hidden positional mismatch being described.'),
('A17','FK, IK, bones/joints, over-extension goals, bend-direction problems, skin deformation, added controls and expressive freedom are retained.','The source180-degree overgeneralization is correctly distinguished from joint rotation, IK bend direction and skin deformation. This necessary clarification should remain.','P2','04:24–04:38','Separate the observed Lili sleeve contour from the hypothetical added-control implementation. A victory shot cannot establish the internal rig or show a controlled fixed-hand deformation test.'),
('A18','Single-axis versus multi-axis path, neck and wrist examples, linked shoulder/clavicle/translation, axis timing and easing, emotional path differences and final gaze are retained.','Actual head comparisons, live curves and head/eye-angle chips are visible. Several game cuts hide the object the line asks viewers to inspect.','P2','01:39–02:32;03:12–03:20;06:00–06:17','Match the promised three paths to three clearly labeled views. Use an unobstructed tablet-lift moment and enlarge the eye-only contribution; the current acquisition popup covers the narrated motion and gaze.'),
]
for id,coverage,understanding,pri,time,action in rows:
 data['records'].append({'id':id,'sourceCoverage':coverage,'understanding':understanding,'issues':[{'priority':pri,'time':time,'finding':action,'action':'See Korean review report for the concrete correction.'}],'textReview':'complete','visualReview':'six current encoded samples plus targeted follow-up where recorded; not full motion/audio certification'})
for r in data['records']:
 r['visualReview']='current encoded targeted samples reviewed; complete source/current text read; no full-video human listening claim'
 for i in r['issues']:
  i['finding']=i['finding'].replace('speech-free','captioned-explanation-free')
 if r['id']=='A06':
  r['issues']=[{'priority':'P1','time':'02:13–02:33','finding':'Narration promises three attack types and their shared timing axis; targeted encoded frames show two sword poses, then a cancel comparison and gameplay. Neither the three matching attacks nor their common three-row timeline is shown.','action':'Show jab / broad swing / projectile on a common timeline, with start, active and next-input markers. Retain the existing rapid-attack and follow-through lesson.'}]
 if r['id']=='A08':
  r['issues']=[{'priority':'P1','time':'00:57–04:45, especially04:36–04:44','finding':'The script promises incremental adjustments on one model. Current cuts repeatedly return to battles; during wing/volume explanation the sampled picture shows sword fighters and a monster, without an isolated wing or volume comparison.','action':'Keep the same reference pose and show each changed head/torso/arm/wrist/weight/foot/wing feature beside the unchanged previous state. Use actual-game confirmation after viewers can identify the change.'}]
data['scope']='A01–A18 full source/current KO-caption audit plus144 targeted encoded frames. Review only: no masters, TTS, uploads, schedules or source lessons changed.'
data['basis']='All18 current caption/video hashes verified against pacing-v3 manifest. Cached complete Japanese automatic source transcripts or English burned-caption OCR were read. Automated source transcription is not a verbatim official-script guarantee. Four decoded mix windows establish nonzero audio, so caption gaps are described as explanation gaps, not total silence.'
data['humanListening']='Not performed; this report does not certify final voice quality or complete motion playback.'
